## Why This Is Asked

This question tests mastery of rope-like data structures for dynamic sequences with cut-paste operations while maintaining fast range queries.

## Key Concepts

- **Implicit treap / rope**: Uses position as the key rather than explicit values
- **Split and merge operations**: Fundamental primitives for manipulating segments
- **Augmented data**: size and range sum maintained at each node
- **Edge cases**: Properly handling when dest overlaps with [l, r]

## Code Example

```javascript
class Node {
  constructor(v) {
    this.v = v;
    this.pr = Math.random();
    this.l = this.r = null;
    this.sz = 1;
    this.sum = v;
  }
}

function upd(t) {
  if (!t) return;
  t.sz = 1 + sz(t.l) + sz(t.r);
  t.sum = t.v + sum(t.l) + sum(t.r);
}

function split(t, k, l, r) {
  if (!t) return [null, null];
  if (sz(t.l) >= k) {
    let [a, b] = split(t.l, k, l, r);
    t.l = b; upd(t);
    return [a, t];
  } else {
    let [a, b] = split(t.r, k - sz(t.l) - 1, l, r);
    t.r = a; upd(t);
    return [t, b];
  }
}

function merge(a, b) {
  if (!a || !b) return a || b;
  if (a.pr < b.pr) {
    a.r = merge(a.r, b); upd(a); return a;
  } else {
    b.l = merge(a, b.l); upd(b); return b;
  }
}

function rangeSum(t, l, r) {
  let [a, bc] = split(t, l);
  let [b, c] = split(bc, r - l + 1);
  let res = sum(b);
  t = merge(a, merge(b, c));
  return res;
}

function moveSegment(t, l, r, dest) {
  let len = r - l + 1;
  let [a, bc] = split(t, l);
  let [b, c] = split(bc, len);
  t = merge(a, c);

  let pos = dest <= l ? dest : dest - len;
  let [x, y] = split(t, pos);\n  return merge(merge(x, b), y);
}
```

## Why This Is Asked

This question tests understanding of order statistics in dynamic sets, along with practical implementation details like lazy deletion and handling duplicates.

## Key Concepts

- **Median of a dynamic set**: the middle element (or average of two middle elements) when sorted
- **Two-heap approach**: max-heap for the lower half, min-heap for the upper half
- **Lazy deletion**: defer actual removal until top operations, tracking deletions via a count map
- **Duplicate handling**: maintain frequency counts rather than storing duplicate values multiple times in the heaps

## Code Example

```javascript
class MedianFinder {
  constructor() {
    this.low = new MaxHeap();    // max-heap for lower half
    this.high = new MinHeap();   // min-heap for upper half
    this.delayed = new Map();    // lazy deletion map
  }

  insert(num) {
    if (this.low.isEmpty() || num <= this.low.peek()) {
      this.low.push(num);
    } else {
      this.high.push(num);
    }
    this.rebalance();
  }

  rebalance() {
    if (this.low.size() > this.high.size() + 1) {
      this.high.push(this.low.pop());
    } else if (this.high.size() > this.low.size()) {
      this.low.push(this.high.pop());
    }
  }

  erase(num) {
    this.delayed.set(num, (this.delayed.get(num) || 0) + 1);
    if (num <= this.low.peek()) {
      this.low.deleted++;
    } else {
      this.high.deleted++;
    }
    this.rebalance();
  }

  getMedian() {
    this.prune(this.low);
    this.prune(this.high);
    if (this.low.size() > this.high.size()) {
      return this.low.peek();
    }
    return (this.low.peek() + this.high.peek()) / 2;
  }
}
```

